#!/usr/bin/env bash
set -euo pipefail

TARGET_BRANCH="work/v0.2.0-appsscript"
if [ "$(git rev-parse --is-inside-work-tree 2>/dev/null || true)" != "true" ]; then echo "请在 DuanOS 仓库的 Codespace 终端中运行本脚本"; exit 1; fi
git fetch origin "$TARGET_BRANCH"
git switch "$TARGET_BRANCH" 2>/dev/null || git switch -c "$TARGET_BRANCH" --track "origin/$TARGET_BRANCH"
git pull --ff-only origin "$TARGET_BRANCH"

mkdir -p "$(dirname '.dev.vars.example')"
printf %s 'QVBQU19TQ1JJUFRfV0VCX0FQUF9VUkw9CkFQUFNfU0NSSVBUX1NIQVJFRF9TRUNSRVQ9CkRVQU5PU19PV05FUl9QQVNTV09SRF9IQVNIPQo=' | base64 -d > '.dev.vars.example'

mkdir -p "$(dirname 'docs/REVIEW-v0.2.0.md')"
printf %s '' | base64 -d > 'docs/REVIEW-v0.2.0.md'

mkdir -p "$(dirname 'tests/backend.test.ts')"
printf %s '' | base64 -d > 'tests/backend.test.ts'

mkdir -p "$(dirname 'tests/app.ui.test.tsx')"
printf %s '' | base64 -d > 'tests/app.ui.test.tsx'

mkdir -p "$(dirname 'apps-script/Code.gs')"
printf %s '' | base64 -d > 'apps-script/Code.gs'

mkdir -p "$(dirname 'apps-script/appsscript.json')"
printf %s '' | base64 -d > 'apps-script/appsscript.json'

mkdir -p "$(dirname 'apps-script/README.md')"
printf %s '' | base64 -d > 'apps-script/README.md'

mkdir -p "$(dirname 'docs/APPS-SCRIPT-DEPLOY.md')"
printf %s '' | base64 -d > 'docs/APPS-SCRIPT-DEPLOY.md'

rm -f functions/_lib/google.ts functions/_lib/oauth.ts functions/api/auth/callback.ts
git diff --check
echo '文件已应用，开始安装依赖和检查…'
npm ci
npm run typecheck
npm test -- --runInBand
npm run build:cloudflare
git add -A
if git diff --cached --quiet; then echo '没有新的变更需要提交'; else git commit -m 'feat: complete Apps Script bridge migration'; fi
git push origin "$TARGET_BRANCH"
echo '上传完成。当前提交：'
git rev-parse HEAD
